// FIXED 2026-07-11: iterate + service-recovery gate + quiet hours + CTIA STOP disclosure.
const QUIET_START = 8, QUIET_END = 21;

const TEMPLATES = {
  2: 'Hi {firstName}, {ownerFirstName} here from {businessName}. Thanks again for the opportunity to work with you. If you have 30 seconds, would you share your experience in a quick Google review? {reviewLink} Reply STOP to opt out.',
  3: 'Quick follow-up — if you haven’t had a chance yet, a quick Google review helps others know they can trust us. {reviewLink} Reply STOP to opt out.'
};

const items = ($input.first().json.customers || []);
const out = [];

for (const c of items) {
  // Service recovery gate
  if (c.checkinNegative) continue;

  // Quiet hours check (recipient local)
  const tz = c.timezone || 'America/New_York';
  const localHour = parseInt(new Date().toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: tz }), 10);
  if (localHour < QUIET_START || localHour >= QUIET_END) continue;

  const t = c.nextTouch;
  let text = TEMPLATES[t]
    .replace(/\{firstName\}/g, c.firstName || '')
    .replace(/\{ownerFirstName\}/g, c.clientOwnerFirstName || '')
    .replace(/\{businessName\}/g, c.clientBusinessName || '')
    .replace(/\{reviewLink\}/g, c.reviewLink || '');

  out.push({ json: { ...c, text, lead_id: c.closeLeadId, contact_id: c.closeContactId, local_phone: c.clientSenderPhone, remote_phone: c.phone } });
}

return out;

// FIXED: iterate over all items so 10-item batches process fully (was: only first)
// n8n pairs each Get Close SMS History response with its matching Loop Batches item.
const items = $input.all();
const customers = $('Loop Batches (10)').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const customer = customers[i]?.json;
  if (!customer) continue;
  const history = (items[i].json.data || []).sort((a, b) => new Date(a.date_created) - new Date(b.date_created));

  // Sticky sender: last outbound's local_phone, fallback to customer.local_phone
  const lastOut = [...history].reverse().find(a => a.direction === 'outbound');
  const stickyLocal = lastOut ? lastOut.local_phone : customer.local_phone;

  // Reply gate: skip if inbound reply after last outbound
  if (lastOut) {
    const lastOutTime = new Date(lastOut.date_created).getTime();
    const hasReply = history.some(a => a.direction === 'inbound' && new Date(a.date_created).getTime() > lastOutTime);
    if (hasReply) continue;
  }

  out.push({ json: { ...customer, local_phone: stickyLocal } });
}

return out;
